
const minute = 60_000;
const hour = 60 * minute;
const day = 24 * hour;

function isoAgo(ms) {
  return new Date(Date.now() - ms).toISOString();
}

function escapeHtml(value='') {
  return String(value)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#039;');
}

function stressParagraph(topic, index) {
  return `<p><strong>${escapeHtml(topic)}</strong> · bloque ${index}. Este párrafo existe para estresar ancho, ritmo vertical y edición continua. Incluye <em>énfasis</em>, <u>subrayado</u>, <s>contenido descartado</s>, <code>inline-${index}</code> y un <a href="https://example.com/mock-${index}">enlace mock</a> para comprobar estilos mezclados sin depender de datos externos.</p>`;
}

function makeStressBody(topic, sections=8, dense=false) {
  const parts = [
    `<p>Documento mock de validación para <strong>${escapeHtml(topic)}</strong>. Está cargado intencionalmente con contenido heterogéneo para probar scroll, sticky, selección, guardado y renderizado.</p>`,
    `<div class="doc-callout"><strong>Dato mock:</strong> ninguna cifra o decisión de este documento representa información real. El objetivo es validar la interfaz.</div>`
  ];
  for (let i=1;i<=sections;i++) {
    parts.push(`<h2>${i}. ${escapeHtml(topic)} · escenario ${i}</h2>`);
    parts.push(stressParagraph(topic,i));
    if (dense || i % 2 === 0) parts.push(`<p>Una segunda línea extensa fuerza wrapping en pantallas pequeñas y permite verificar que el documento nunca genere overflow horizontal. La experiencia debe seguir siendo legible incluso cuando el contenido crece de forma poco elegante, como ocurre en datos reales.</p>`);
    if (i % 3 === 0) parts.push(`<blockquote><p>“Una interfaz resistente no solo se ve bien con tres líneas: también conserva jerarquía cuando el contenido se vuelve largo, irregular y repetitivo.”</p></blockquote>`);
    if (i % 4 === 0) parts.push(`<ul><li>Acción mock ${i}.1 con texto corto.</li><li>Acción mock ${i}.2 con una descripción considerablemente más larga para comprobar alineación y wrapping.</li><li>Acción mock ${i}.3 con <strong>prioridad visual</strong>.</li></ul>`);
    if (i % 5 === 0) parts.push(`<ul class="checklist"><li class="done">Validar flujo ${i}.1</li><li>Revisar comportamiento sticky ${i}.2</li><li>Comprobar persistencia ${i}.3</li><li>Probar interacción táctil ${i}.4</li></ul>`);
    if (i % 6 === 0) parts.push(`<details class="spoiler"><summary>Detalles opcionales · escenario ${i}</summary><p>Contenido oculto mock para probar disclosure progresivo. Abrir y cerrar este bloque no debe mover ni romper el ancho de la página.</p><p>Segunda línea del desplegable para producir un cambio de altura visible.</p></details>`);
    if (i % 7 === 0) parts.push(`<pre><code>// bloque mock ${i}
const module = "${escapeHtml(topic).replaceAll('"','&quot;')}";
const status = "stress-test";
console.log(module, status);</code></pre>`);
    if (i % 8 === 0) parts.push(`<table><thead><tr><th>Flujo</th><th>Estado</th><th>Notas</th></tr></thead><tbody><tr><td>Crear</td><td>Mock</td><td>Escenario ${i}</td></tr><tr><td>Editar</td><td>Mock</td><td>Texto largo que debe envolver sin overflow</td></tr><tr><td>Guardar</td><td>Mock</td><td>Persistencia local</td></tr></tbody></table>`);
    if (i % 4 === 0) parts.push('<hr>');
  }
  return parts.join('');
}

const builtins = [{"id": "brief", "title": "Brief · Bardo conversacional", "description": "Qué debe poder hacer Bardo cuando conversar sea la forma más rápida de avanzar.", "body": "\n<p>La capa conversacional de Bardo debe permitir que una persona <strong>haga trabajo sin aprenderse el sistema</strong>. La conversación es una entrada natural a Docs, Kanban, Calendar y Planner; no una pantalla aparte que compita con ellos.</p>\n<p>La sensación objetivo es simple: si alguien sabe explicar lo que necesita, ya sabe usar Bardo. El sistema debe encargarse de traducir intención a estructura sin pedir decisiones que todavía no son necesarias.</p>\n<h2>Principio central</h2>\n<blockquote><p>La conversación no reemplaza los módulos. Los vuelve más fáciles de usar y reduce el costo mental de empezar.</p></blockquote>\n<p>Eso implica que una petición como <em>“recuérdame enviar el brief el lunes”</em> debería convertirse en una tarea útil con los mínimos datos posibles. Si Bardo puede inferir algo con seguridad, no debería convertirlo en otra casilla.</p>\n<h2>Qué debería poder hacer</h2>\n<ul><li>Crear tareas con lenguaje natural y completar detalles después.</li><li>Preguntar qué queda pendiente sin abrir el Kanban.</li><li>Generar minutas desde una conversación o canal de Discord.</li><li>Crear un documento y entrar directamente a escribir.</li><li>Encontrar un documento por contexto, aunque no recuerdes su nombre exacto.</li><li>Proponer un evento cuando detecta una fecha, sin crearlo silenciosamente.</li></ul>\n<div class=\"callout\"><strong>Regla:</strong> una acción reversible puede sentirse inmediata. Una acción sensible necesita una confirmación clara y breve.</div>\n<h2>Flujo de ejemplo</h2>\n<ol><li>La persona escribe: <strong>“Bardo, arma la minuta de lo que hablamos hoy y déjame las tareas.”</strong></li><li>Bardo resume decisiones y detecta acciones.</li><li>Muestra una vista previa compacta: minuta + tres tareas.</li><li>La persona confirma una sola vez.</li><li>La minuta queda en Docs y las tareas aparecen en Kanban con links cruzados.</li></ol>\n<h2>Checklist de la primera versión</h2>\n<ul class=\"checklist\"><li class=\"done\">Entender creación de tareas simples.</li><li class=\"done\">Consultar tareas pendientes.</li><li>Crear documentos desde una conversación.</li><li>Generar minuta a partir de mensajes recientes.</li><li>Proponer eventos a partir de fechas detectadas.</li></ul>\n<h2>Formato y tono</h2>\n<p>Bardo debería responder con lenguaje corto y operativo. <strong>No necesitamos párrafos de asistente genérico</strong> después de cada acción. Un “Listo, agregué 3 tareas” es mejor que una explicación larga de lo que acaba de pasar.</p>\n<p>Los detalles técnicos pueden existir, pero deben aparecer solo cuando aportan algo. Por ejemplo, un identificador interno como <code>doc_01JX8Z</code> jamás debería competir visualmente con el nombre humano del documento.</p>\n<details class=\"spoiler\"><summary>Mostrar notas internas del prototipo</summary><p>Esta sección sirve para probar un bloque de contenido plegable. En Bardo podría utilizarse para contexto secundario, transcripciones largas o información que no hace falta leer en el recorrido principal.</p><p>También nos permite comprobar si un bloque que cambia de altura rompe el scroll, el header difuso o el comportamiento sticky de la toolbar.</p></details>\n<h2>Contrato mínimo de una acción</h2>\n<table><thead><tr><th>Acción</th><th>Dato mínimo</th><th>Después</th></tr></thead><tbody><tr><td>Tarea</td><td>Título</td><td>Fecha, responsable y prioridad opcionales</td></tr><tr><td>Documento</td><td>Nada</td><td>Entrar directamente a escribir</td></tr><tr><td>Evento</td><td>Qué + cuándo</td><td>Invitados y descripción opcionales</td></tr></tbody></table>\n<h2>Ejemplo de payload</h2>\n<pre><code>{\n  \"intent\": \"create_task\",\n  \"title\": \"Enviar brief de Docs\",\n  \"due\": \"2026-08-24\",\n  \"confidence\": 0.94\n}</code></pre>\n<p>El payload existe para el sistema, no para la persona. La interfaz debe traducirlo a algo legible y accionable.</p>\n<hr/>\n<h2>Qué no queremos</h2>\n<p>No queremos una home llena de widgets, métricas y accesos rápidos solo porque el producto tiene varios módulos. Tampoco queremos que la capa conversacional agregue una nueva taxonomía de <u>agentes</u>, <u>skills</u> y <u>workflows</u> que la persona tenga que aprender.</p>\n<p>La complejidad debe vivir detrás. Delante queda una interfaz tranquila, predecible y fácil de retomar incluso después de varios días sin usarla.</p>\n<h2>Notas para la siguiente prueba</h2>\n<p>En mobile debemos observar especialmente tres cosas: cuándo la toolbar se vuelve sticky, si el título sigue manteniendo jerarquía cuando desaparece de pantalla y si abrir/cerrar el spoiler produce algún salto incómodo. También conviene seleccionar texto cerca del final del documento para comprobar que la edición sigue siendo estable después de un scroll largo.</p>\n<p>Si todo se siente bien aquí, el paso siguiente es llevar la misma estructura a HeroUI sin perder este comportamiento. La migración debería cambiar componentes y arquitectura, <em>no volver a discutir la experiencia desde cero</em>.</p>\n", "origin": "Creado en Bardo"}, {"id": "minuta", "title": "Minuta · Weekly de producto", "description": "Decisiones, acuerdos y próximos pasos de la weekly de producto.", "body": "\n<p>Revisión del estado de Bardo y decisiones para la siguiente iteración. El foco de esta weekly fue simplificar los módulos antes de integrarlos nuevamente.</p>\n<h2>Resumen</h2>\n<p>Se acordó trabajar cada módulo como una experiencia autocontenida y funcional. Docs será el primero porque permite fijar patrones que luego reutilizaremos: navegación, topbar, estados, responsive, acciones secundarias y persistencia.</p>\n<blockquote><p>Antes de pensar en integración, cada módulo tiene que ser suficientemente bueno como para que quisiéramos usarlo por sí solo.</p></blockquote>\n<h2>Decisiones</h2>\n<ul>\n<li><strong>Mobile first real.</strong> No diseñar desktop y comprimirlo después.</li>\n<li><strong>Notion Light.</strong> El contenido manda y el chrome desaparece.</li>\n<li><strong>Progressive disclosure.</strong> Lo secundario vive en menús o aparece cuando hace falta.</li>\n<li><strong>HTML primero.</strong> Resolver interacción antes de migrar a React + HeroUI.</li>\n</ul>\n<h2>Temas discutidos</h2>\n<h3>Header</h3>\n<p>Se descartó el header de dashboard con avatar, nombre del producto y subtítulo. En documentos abiertos queremos una navegación mínima: volver, editar/listo y acciones secundarias.</p>\n<h3>Editor</h3>\n<p>La toolbar debe empezar en el flujo, después de título, descripción y metadata. Al hacer scroll se mantiene visible usando comportamiento <code>sticky</code>. Esto evita que las herramientas compitan con el documento cuando todavía no son necesarias.</p>\n<h3>Scroll</h3>\n<p>Regla estricta: <strong>una vista, un scroll vertical</strong>. Nada de contenedores internos robando el gesto, nada de scroll horizontal accidental y nada de barras secundarias que conviertan el documento en una colección de paneles.</p>\n<details class=\"spoiler\">\n<summary>Notas que no necesitan estar abiertas siempre</summary>\n<p>Se habló de una posible vista de historial y versiones, pero no entra todavía. También quedó fuera una arquitectura de carpetas porque agrega decisiones tempranas y puede resolverse más adelante con búsqueda y organización ligera.</p>\n</details>\n<h2>Acciones</h2>\n<ul class=\"checklist\">\n<li class=\"done\">Corregir navegación del HTML para que funcione incluso con JS bloqueado.</li>\n<li class=\"done\">Mover toolbar desde fixed a sticky.</li>\n<li class=\"done\">Eliminar scrolls anidados.</li>\n<li>Probar documentos largos con varios tipos de bloque.</li>\n<li>Validar el comportamiento en iPhone pequeño y grande.</li>\n<li>Definir el set final de acciones del menú “más”.</li>\n</ul>\n<h2>Riesgos</h2>\n<table>\n<thead><tr><th>Riesgo</th><th>Señal</th><th>Respuesta</th></tr></thead>\n<tbody>\n<tr><td>Demasiado chrome</td><td>El documento parece dashboard</td><td>Quitar superficies y etiquetas</td></tr>\n<tr><td>Toolbar sobrecargada</td><td>Scroll lateral o demasiados iconos</td><td>Dejar acciones frecuentes y agrupar el resto</td></tr>\n<tr><td>Jerarquía débil</td><td>Meta y controles compiten con título</td><td>Revisar tamaño, contraste y proximidad</td></tr>\n</tbody>\n</table>\n<hr/>\n<h2>Próxima sesión</h2>\n<p>Revisar el stress test en mobile. Si el comportamiento del scroll y la toolbar se mantiene estable, empezar a definir el contrato de componentes para HeroUI.</p>\n", "origin": "Desde Discord"}, {"id": "principios", "title": "Principios UX · Docs", "description": "Reglas simples para que Docs se sienta ligero, predecible y fácil de retomar.", "body": "\n<p>Docs debe sentirse como <strong>Notion Light</strong>, no como una suite de oficina. Cada decisión tiene que reducir fricción para leer, escribir y retomar contexto.</p>\n<h2>1. Contenido antes que chrome</h2>\n<p>El título pertenece al documento, no al header de la aplicación. El header sirve para orientarse y ejecutar acciones; no para repetir el nombre del producto.</p>\n<blockquote><p>Si un elemento no ayuda a navegar, editar o entender el documento, probablemente sobra.</p></blockquote>\n<h2>2. Proximidad expresa relación</h2>\n<p>Título y descripción forman una unidad. La metadata está relacionada, pero es secundaria. La toolbar pertenece a otro grupo funcional y por eso necesita una separación perceptible antes del cuerpo.</p>\n<h2>3. Menos decisiones al crear</h2>\n<p>Crear un documento no debería abrir un modal con tipo, carpeta, plantilla y permisos. Debe abrir una hoja vacía. La persona puede decidir lo demás más tarde, si alguna vez lo necesita.</p>\n<ul class=\"checklist\">\n<li class=\"done\">Título opcional al comenzar.</li>\n<li class=\"done\">Descripción opcional.</li>\n<li class=\"done\">Autosave.</li>\n<li>Historial de versiones solo cuando exista una necesidad real.</li>\n</ul>\n<h2>4. Formato suficiente</h2>\n<p>El editor necesita <strong>negrita</strong>, <em>cursiva</em>, <u>subrayado</u>, <del>tachado</del>, títulos, listas, links, citas, código, separadores y bloques plegables. No necesita convertirse en un procesador de texto completo.</p>\n<div class=\"callout\">Un set pequeño de bloques bien resuelto es más valioso que treinta opciones con comportamiento inconsistente.</div>\n<h3>Texto técnico</h3>\n<pre><code>.editor-toolbar {\n  position: sticky;\n  top: var(--topbar-offset);\n  max-width: 100%;\n}</code></pre>\n<h3>Atajos</h3>\n<p>En desktop podemos permitir <kbd>⌘</kbd> + <kbd>B</kbd> para negrita y <kbd>⌘</kbd> + <kbd>K</kbd> para links, pero la experiencia principal no puede depender de aprender shortcuts.</p>\n<details class=\"spoiler\">\n<summary>¿Por qué “spoiler” en Docs?</summary>\n<p>El nombre puede cambiar a “Desplegable” o “Detalles”. Lo importante es el patrón: esconder contexto que existe, pero que no debería aumentar la longitud percibida del documento hasta que alguien decida verlo.</p>\n<p>Puede servir para transcripciones, notas técnicas, alternativas descartadas o información adicional.</p>\n</details>\n<h2>5. Scroll predecible</h2>\n<p>La página completa es la superficie que se desplaza. El header es sticky. La toolbar se vuelve sticky solo después de alcanzar su posición. El contenido largo sigue siendo una sola continuidad vertical.</p>\n<ol>\n<li>Entrar al documento.</li>\n<li>Leer título y contexto.</li>\n<li>Encontrar la toolbar si se está editando.</li>\n<li>Hacer scroll sin cambiar de “zona”.</li>\n<li>Volver arriba sin saltos.</li>\n</ol>\n<h2>6. Estados silenciosos</h2>\n<p>“Guardando…” y “Guardado” deben existir, pero sin convertirse en banners. El sistema necesita inspirar confianza sin interrumpir.</p>\n<hr/>\n<h2>Prueba de densidad</h2>\n<p>Este último tramo existe a propósito para estresar la longitud. Queremos observar si, después de varias pantallas de contenido, la lectura sigue cómoda y la navegación sigue siendo evidente. También es útil para evaluar si el header sticky mantiene una separación clara cuando los encabezados pasan por debajo.</p>\n<p>Si sentimos que el documento necesita cards para organizarse, primero revisaremos spacing, headings y divisores. Las cards serán una excepción, no el mecanismo por defecto para fabricar jerarquía.</p>\n<p>La meta es que una persona pueda abrir esto desde Discord, entender dónde está en segundos, editar algo rápidamente y cerrar sin tener que “gestionar” el documento como objeto administrativo.</p>\n", "origin": "Creado en Bardo"}];

