export function createSeedDocs() {
  const builtinDocs = builtins.map((doc,index) => ({
    ...doc,
    body: doc.body.replaceAll('class="callout"','class="doc-callout"'),
    createdAt: isoAgo((index + 4) * day),
    updatedAt: isoAgo([12*minute, 3*hour, 24*hour][index]),
    builtin: true,
    stress: false,
  }));
  const stressDocs = stressSpecs.map((spec,index) => ({
    id: spec[0],
    title: spec[1],
    description: spec[2],
    body: makeStressBody(spec[1], spec[3], spec[5]),
    origin: spec[4],
    createdAt: isoAgo((index + 2) * day),
    updatedAt: isoAgo((index * 37 + 7) * minute),
    builtin: false,
    stress: true,
  }));
  return [...builtinDocs, ...stressDocs];
}

export const SEED_COUNT = 21;
